<div class="lead-work-heading"><div><div class="work-badges"><span class="work-kind">{{ $item->kind }}</span><span class="work-status {{ strtolower($item->status) }}">{{ $item->status }}</span>@if($item->priority!=='Normal')<span class="work-priority">{{ $item->priority }} priority</span>@endif</div><h3>{{ $item->title }}</h3><small>Assigned to {{ $item->assignee?->name ?? 'Unassigned' }}</small></div><div class="work-due {{ $item->status==='Pending' && $item->due_at->isPast() ? 'lead-overdue' : '' }}"><small>{{ $item->status==='Pending' && $item->due_at->isPast() ? 'Overdue · Action needed' : 'Due date' }}</small><time datetime="{{ $item->due_at->toIso8601String() }}">{{ $item->due_at->format('d M Y · H:i') }} IST</time></div></div>
